package egraph_test

import (
	"context"
	"fmt"
	"math"
	"testing"
	"time"

	"github.com/tmc/lib/nvidia/x/cudalaunch"
	"github.com/tmc/lib/nvidia/x/cudatest"
	"github.com/tmc/lib/nvidia/x/egraph"
	"github.com/tmc/lib/nvidia/x/nvrtcx"
)

// TestCompositeKernelRejectsDeeperTrees covers the last generator in this file
// that ignored its input. generateCompositeKernel never reads the tree it is
// handed, so add(x, w) and add(x, mul(w, w)) generated byte-identical source:
// the multiply was dropped in silence, and the kernel has only two input
// buffers to pass anyway. Unlike the memcpy fallback, the emitted arithmetic is
// right for a genuine leaf add -- TestGeneratedCompositeMatchesReference checks
// that on hardware -- so the fix is to reject the shapes it cannot express
// rather than to change what it computes.
func TestCompositeKernelRejectsDeeperTrees(t *testing.T) {
	leaf := &egraph.Expr{Op: "add", Children: []*egraph.Expr{{Op: "x"}, {Op: "w"}}}
	nested := &egraph.Expr{Op: "add", Children: []*egraph.Expr{
		{Op: "x"},
		{Op: "mul", Children: []*egraph.Expr{{Op: "w"}, {Op: "w"}}},
	}}
	a, errA := egraph.GenerateCUDA(leaf, egraph.CodegenOptions{KernelName: "K"})
	b, errB := egraph.GenerateCUDA(nested, egraph.CodegenOptions{KernelName: "K"})
	if errA != nil {
		t.Fatalf("GenerateCUDA(add(x, w)): %v", errA)
	}
	// (x + w*w) is not a two-input elementwise add and has no kernel here.
	// Emitting one for it silently drops the multiply.
	if errB == nil && a == b {
		t.Fatalf("add(x, w) and add(x, mul(w, w)) generated identical source; "+
			"the generator ignores its expression:\n%s", b)
	}
	if errB == nil {
		t.Errorf("GenerateCUDA(add(x, mul(w, w))) returned source for an "+
			"expression the kernel does not implement:\n%s", b)
	}
}

// TestGeneratedCompositeMatchesReference runs the composite kernel on the
// device and checks it against the elementwise sum. This is the value oracle
// the compile gate cannot supply: an "add" kernel that returns anything at all
// compiles, and only comparing numbers shows whether it added.
func TestGeneratedCompositeMatchesReference(t *testing.T) {
	dev := cudatest.Require(t)
	defer dev.Close()
	major, minor, err := dev.ComputeCapability()
	if err != nil {
		t.Fatal(err)
	}

	expr := &egraph.Expr{Op: "add", Children: []*egraph.Expr{{Op: "x"}, {Op: "w"}}}
	src, err := egraph.GenerateCUDA(expr, egraph.CodegenOptions{KernelName: "Composite"})
	if err != nil {
		t.Fatalf("GenerateCUDA: %v", err)
	}
	compiled, err := nvrtcx.Compile(src,
		nvrtcx.WithName("composite.cu"),
		nvrtcx.WithFlag(fmt.Sprintf("--gpu-architecture=sm_%d%d", major, minor)),
		nvrtcx.WithOutput(nvrtcx.OutputCUBIN),
		nvrtcx.WithNoCache(),
	)
	if err != nil {
		t.Fatalf("compile: %v", err)
	}
	mod, err := compiled.Load(dev)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	defer mod.Unload()
	fn, err := mod.GetFunction("Composite")
	if err != nil {
		t.Fatal(err)
	}
	stream, err := dev.NewStream()
	if err != nil {
		t.Fatal(err)
	}
	defer stream.Destroy()

	const n = 1024
	a := make([]float32, n)
	b := make([]float32, n)
	for i := range a {
		a[i] = float32((i*13)%17-8) * 0.5
		b[i] = float32((i*7)%11-5) * 0.25
	}
	da := deviceSlice(t, dev, a)
	db := deviceSlice(t, dev, b)
	dout := deviceSlice(t, dev, make([]float32, n))
	for _, free := range []func() error{da.Free, db.Free, dout.Free} {
		defer free()
	}

	if err := cudalaunch.Kernel(fn).Grid(4, 1).Block(256).On(stream).Launch(
		da, db, dout, int32(n),
	); err != nil {
		t.Fatalf("launch: %v", err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := stream.Synchronize(ctx); err != nil {
		t.Fatalf("synchronize: %v", err)
	}
	got := make([]float32, n)
	if err := dev.WithContext(func() error { return dout.CopyToHost(got) }); err != nil {
		t.Fatal(err)
	}
	for i := range got {
		want := a[i] + b[i]
		if math.Abs(float64(got[i]-want)) > 1e-6 {
			t.Fatalf("out[%d] = %v, want %v", i, got[i], want)
		}
	}
}
